-- 栈应用：括号匹配的扫描与成对规则。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '括号匹配','扫描左括号时入栈，右括号必须与当前栈顶成对；结束时栈为空才匹配。',course.id,parent.id,'cs408-parentheses-matching','AISTU',1,'REVIEWED',5,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-parentheses-matching' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-parentheses-matching',1,'REVIEWED','括号匹配',JSON_OBJECT('summary','从左到右扫描字符：左括号压栈；遇到右括号时，若栈空或类型与栈顶不匹配则失败，否则弹出栈顶。扫描结束时只有栈为空才全部匹配，时间 O(n)、最坏辅助空间 O(n)。','steps',JSON_ARRAY('从左到右逐字符扫描','左括号压入栈顶','右括号必须匹配当前栈顶类型','栈空时出现右括号立即失败','扫描结束后栈为空才成功'),'prerequisite',JSON_OBJECT('contentKey','cs408-stack-lifo','title','栈的 LIFO 语义与基本操作','description','先掌握只能从栈顶读取和弹出的限制。'),'nextStep',JSON_OBJECT('contentKey','cs408-expression-evaluation','title','表达式转换与求值','description','继续学习两个栈中元素的进出规则。')),JSON_OBJECT('id','parentheses-matching-v1','prompt','括号串扫描结束后，什么条件说明所有括号都匹配？','options',JSON_ARRAY(JSON_OBJECT('id','STACK_EMPTY_END','text','栈为空，且扫描中没有出现失配'),JSON_OBJECT('id','LAST_IS_RIGHT','text','最后一个字符是右括号')),'correctOptionId','STACK_EMPTY_END','correctExplanation','正确：遗留左括号会仍保留在栈中，扫描中失配也不能被最后字符修复。','incorrectExplanation','不正确：最后字符的类型不能判断前面是否有遗留或类型失配。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-parentheses-matching' AND existing.content_version=1 WHERE point.content_key='cs408-parentheses-matching' AND existing.id IS NULL;
